'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const R=window.RESEARCH,E=window.EDITORIAL;
const specialties=R.specialties, sources=[...R.sources,...E.sources], byId=Object.fromEntries(specialties.map(s=>[s.id,s])), sourceById=Object.fromEntries(sources.map(s=>[s.id,s]));
const groups={
 'Robots & mechanisms':['spacecraft-mechanisms','space-robotics','orbital-servicing','lunar-construction','humanoids-wearables'],
 'Living & working in space':['habitats-life-support','eva-human-systems','crew-operations','microgravity-manufacturing'],
 'Vehicles & propulsion':['gnc','chemical-propulsion','electric-propulsion','nuclear-space','aerodynamics-entry','aviation-propulsion','structures-manufacturing'],
 'Power, heat & intelligence':['avionics','space-power','thermal-cryogenic','rf-optical'],
 'Ocean, defense & environments':['underwater-robotics','defense-engineering','orbital-sustainability','space-environments','planetary-protection'],
 'Integration & assurance':['systems-test']
};
const lensIds={all:specialties.map(s=>s.id),robot:['spacecraft-mechanisms','space-robotics','gnc','orbital-servicing','structures-manufacturing','humanoids-wearables','systems-test','avionics','lunar-construction','underwater-robotics'],habitat:['habitats-life-support','thermal-cryogenic','space-power','eva-human-systems','spacecraft-mechanisms','crew-operations','systems-test','space-robotics','nuclear-space','lunar-construction'],vehicle:['gnc','aerodynamics-entry','chemical-propulsion','electric-propulsion','structures-manufacturing','aviation-propulsion','avionics','systems-test','spacecraft-mechanisms'],underwater:['underwater-robotics','gnc','spacecraft-mechanisms','humanoids-wearables','systems-test','avionics','defense-engineering'],human:['humanoids-wearables','eva-human-systems','aviation-propulsion','gnc','space-power','thermal-cryogenic','defense-engineering'],operations:['crew-operations','systems-test','eva-human-systems','habitats-life-support','space-robotics','gnc']};
const lensLabels={all:'All possibilities',robot:'Space robots',habitat:'Living in space',vehicle:'Extraordinary vehicles',underwater:'Ocean machines',human:'“Iron Man” ideas',operations:'Crew & operations'};
const order=['spacecraft-mechanisms','space-robotics','gnc','orbital-servicing','habitats-life-support','thermal-cryogenic','structures-manufacturing','systems-test',...specialties.map(s=>s.id)];
specialties.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
function readLocal(){try{return JSON.parse(localStorage.getItem('frontier-atlas-v1')||'{}')}catch{return {}}}
let local=readLocal(), saved=new Set((local.saved||[]).filter(id=>byId[id])),notes=local.notes||{},compare=new Set(),activeView='home',returnView='explore',filters={q:'',group:'all',lens:'all',horizon:'2034'},routeId='robot',missionId='yard',horizon='2034';
function persist(){try{localStorage.setItem('frontier-atlas-v1',JSON.stringify({saved:[...saved],notes}))}catch{toast('Storage unavailable. Export your notes to keep them.')}updateSaved();}
function updateSaved(){$('#saved-count').textContent=saved.size;$$('[data-action="save"]').forEach(b=>{const on=saved.has(b.dataset.id);b.setAttribute('aria-pressed',on);b.textContent=b.classList.contains('iconbutton')?(on?'★':'☆'):(on?'★ Saved to your shortlist':'☆ Save this path')})}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function refs(ids){return '<div class="source-links">'+[...new Set(ids||[])].filter(id=>sourceById[id]).map(id=>`<a href="${esc(sourceById[id].url)}" target="_blank" rel="noopener">${esc(sourceById[id].title)} ↗</a>`).join('')+'</div>'}
function ul(items){return '<ul class="bullet-list">'+items.map(s=>`<li>${esc(s)}</li>`).join('')+'</ul>'}
function getGroup(id){return Object.keys(groups).find(g=>groups[g].includes(id))||'Other'}
function intro(kicker,title,desc){return `<div class="page-intro"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="lead">${desc}</p></div>`}
function pathButton(id,label){return byId[id]?`<button data-action="open" data-id="${id}">${esc(label||byId[id].title)} ↗</button>`:''}
function miniSources(title){return sources.filter(s=>s.title.toLowerCase().includes(title.toLowerCase())).slice(0,2).map(s=>s.id)}
function orbitArt(){return `<svg viewBox="0 0 670 650" role="img" aria-label="Conceptual orbital workshop: robotic arm, habitat module, power arrays and Earth. Not a real mission design."><defs><radialGradient id="earth"><stop stop-color="#19424f"/><stop offset=".75" stop-color="#132733"/><stop offset="1" stop-color="#0a1423"/></radialGradient><linearGradient id="metal" x2="0" y2="1"><stop stop-color="#b6c9c9"/><stop offset=".3" stop-color="#6e8991"/><stop offset=".6" stop-color="#294553"/><stop offset="1" stop-color="#101f2f"/></linearGradient><linearGradient id="light" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#c7f09c"/><stop offset="1" stop-color="#69b5b3" stop-opacity="0"/></linearGradient><pattern id="array" width="13" height="14" patternUnits="userSpaceOnUse"><rect width="13" height="14" fill="#1c3a43"/><path d="M0 0H13V14" stroke="#688a81" stroke-width=".8"/></pattern><filter id="glow"><feGaussianBlur stdDeviation="6"/></filter></defs>
<g fill="#b3c9ce">${Array.from({length:50},(_,i)=>`<circle cx="${(i*173+53)%650}" cy="${(i*107+41)%550}" r="${i%4===0?1.4:.65}" opacity="${.18+(i%5)*.13}"/>`).join('')}</g><circle cx="402" cy="575" r="272" fill="url(#earth)"/><path d="M130 573A272 272 0 0 1 666 512" fill="none" stroke="#7dd8d3" stroke-width="5" opacity=".3" filter="url(#glow)"/><path d="M130 573A272 272 0 0 1 666 512" fill="none" stroke="url(#light)" stroke-width="1.6"/><path d="M195 405Q335 360 420 392T620 465M157 450Q290 400 400 435T660 515M230 365Q335 410 355 620M470 312Q435 450 485 635" fill="none" stroke="#335960" opacity=".32"/>
<ellipse cx="340" cy="333" rx="278" ry="171" fill="none" stroke="#516d76" stroke-width=".7" transform="rotate(-23 340 333)"/><ellipse cx="340" cy="333" rx="305" ry="200" fill="none" stroke="#35545f" stroke-dasharray="2 8" stroke-width=".8" transform="rotate(-23 340 333)"/>
<g transform="translate(325 300) rotate(-21)"><path d="M-165 0H157" stroke="#b6c6b1" stroke-width="8"/><rect x="-195" y="-88" width="62" height="174" fill="url(#array)" stroke="#91af9a"/><rect x="129" y="-88" width="62" height="174" fill="url(#array)" stroke="#91af9a"/><path d="M-164 -88V86M160 -88V86" stroke="#a4b29a" stroke-width="3"/><rect x="-98" y="-35" width="180" height="70" rx="27" fill="url(#metal)" stroke="#bed1d2"/><ellipse cx="-80" cy="0" rx="18" ry="33" fill="#3d5965" stroke="#90acb3"/><ellipse cx="77" cy="0" rx="15" ry="32" fill="#213946" stroke="#8caeb5"/><circle cx="78" cy="0" r="11" fill="#101c26" stroke="#b3d2bd"/><path d="M-45 -35V35M12 -35V35M50 -33V33" stroke="#a3bdbe" opacity=".6"/><rect x="-20" y="-56" width="37" height="20" rx="4" fill="#546f75" stroke="#b2c7c6"/><rect x="-15" y="35" width="30" height="27" rx="3" fill="#3e5d68" stroke="#a7bfc0"/><circle cx="0" cy="-61" r="10" fill="#203747" stroke="#d6fa98" stroke-width="3"/>
<path d="M0 -61L-22 -116L38 -151L87 -120" stroke="#152c37" stroke-width="14" fill="none" stroke-linejoin="round"/><path d="M0 -61L-22 -116L38 -151L87 -120" stroke="#b1c2ba" stroke-width="6" fill="none" stroke-linejoin="round"/><g fill="#18373c" stroke="#d6fa98" stroke-width="2"><circle cx="-22" cy="-116" r="9"/><circle cx="38" cy="-151" r="8"/><circle cx="87" cy="-120" r="6"/></g><path d="M89 -119L103 -112L102 -103M89 -119L95 -102L102 -103" fill="none" stroke="#c5d8bd" stroke-width="3"/><rect x="101" y="-109" width="26" height="29" rx="2" fill="#283f4a" stroke="#b8d0cb"/>
</g><g fill="none" stroke="#87a19f" stroke-width=".7"><path d="M370 161L427 104H548"/><path d="M251 299L159 229H49"/><path d="M458 322L517 367H617"/></g><g fill="#c2d2d3" class="diagram-label" font-size="9"><text x="435" y="95">ROBOTIC MANIPULATION</text><text x="49" y="219">HUMAN HABITATION</text><text x="523" y="383">POWER & THERMAL</text><text x="280" y="572" fill="#7c9d9f">LOW EARTH ORBIT / CONCEPT STUDY</text></g><g fill="#d6fa98"><circle cx="370" cy="161" r="3"/><circle cx="251" cy="299" r="3"/><circle cx="458" cy="322" r="3"/></g></svg>`}
function home(){const nicheCount=specialties.reduce((a,s)=>a+s.niches.length,0);return `<div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="pulse"></span> YOUR AEROSPACE FUTURE · 2034—2050</div><h1>Build what<br>comes <em>after.</em></h1><p class="lead">Robots in orbit. Machines on new worlds. Somewhere for humans to live. Find the engineering specialty that puts you inside the work.</p><div class="hero-actions"><a class="button primary" href="#explore">Explore ${specialties.length} paths <span>↗</span></a><a class="button" href="#route">Start with your fit →</a></div><div class="hero-footnote">For a 2033+ graduation · Grounded in today. Open to what comes next.</div></div><div class="hero-art">${orbitArt()}<span class="signal"><span class="pulse"></span> Illustrative architecture · Not a forecast</span></div></section>
<div class="metrics"><div class="metric"><strong>${specialties.length}</strong><span>Specialty pathways</span></div><div class="metric"><strong>${nicheCount}+</strong><span>Deeper technical niches</span></div><div class="metric"><strong>${sources.length}</strong><span>Research references</span></div><div class="metric"><strong>One you.</strong><span>Many ways into the work</span></div></div>
<section class="thesis"><div><div class="eyebrow">THE PERSONAL RECOMMENDATION</div><h2>Become exceptional at making<br><em>physical systems work.</em></h2></div><div><p>Your interests converge on <strong>spacecraft mechanisms, robotics, dynamics, and hands-on testing</strong>. Start there. Use aerospace as your home base, then build a depth that travels between orbital servicing, vehicles, habitats, and Earth industry.</p><p>A promising identity is <strong>“the engineer who makes robots assemble and maintain spacecraft.”</strong> It names a useful capability without betting your entire future on one company or one lunar launch date.</p><a href="#route" class="textlink">See the reasoning and alternatives →</a></div></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">THREE QUESTIONS. THREE DIFFERENT CHOICES.</div><h2>Choose your way in.</h2></div><p>The machine, the technical craft, and the place you work are different layers of a career.</p></div><div class="three-col"><article class="feature-card"><span class="number">01 / THE MISSION</span><h3>What do you want<br>to make possible?</h3><p>Walk through an orbital workshop, a habitat, a lunar worksite, or an ocean robot. See the specialists each one needs.</p><a class="textlink" href="#missions">Explore the machines ↗</a></article><article class="feature-card"><span class="number">02 / THE CRAFT</span><h3>What could you become<br>exceptionally good at?</h3><p>From mechanisms to propulsion to life support. Open the real work, deeper niches, tradeoffs, and employers.</p><a class="textlink" href="#explore">Find your specialization ↗</a></article><article class="feature-card"><span class="number">03 / THE HUMAN</span><h3>Could you be one of<br>the people who goes?</h3><p>Engineering for space and personally working in space are separate tracks. Understand the real routes and the unknowns.</p><a class="textlink" href="#spaceflight">Investigate human spaceflight ↗</a></article></div></section>
<section class="section two-col"><div><div class="eyebrow">YOUR INITIAL SHORTLIST</div><h2>Ambition, with a<br><em>technical center.</em></h2><p>This ordering is a judgment about your interests, not a salary ranking or forecast of job openings.</p><div class="related-buttons">${pathButton('spacecraft-mechanisms')}${pathButton('space-robotics')}${pathButton('gnc')}</div></div><div><div class="recommendation"><span class="rank">1</span><div><h3>Mechanisms + robotics + controls</h3><p>Your strongest fit: moving parts, intelligent machines, assembly, and spacecraft behavior.</p></div></div><div class="recommendation"><span class="rank">2</span><div><h3>Habitat hardware + thermal + reliability</h3><p>A strong alternative if “somewhere to live” becomes more compelling than the vehicle itself.</p></div></div><div class="recommendation"><span class="rank">3</span><div><h3>Integration + test + operations</h3><p>A powerful complement to either path—and relevant experience if flying remains an ambition.</p></div></div></div></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">LOOK FURTHER</div><h2>Don’t choose from a movie poster.</h2></div><p>Choose from the real problems hiding underneath it.</p></div><div class="three-col"><a class="panel" href="#horizons"><h3>What matters in 2034?</h3><p>Three horizons, three scenarios, and the signals worth watching.</p><span class="textlink">Explore the outlook →</span></a><a class="panel" href="#companies"><h3>Who does this today?</h3><p>A searchable employer map tied to specific work and primary sources.</p><span class="textlink">Browse the ecosystem →</span></a><a class="panel" href="#pay"><h3>What about pay and AI?</h3><p>Challenge the assumptions before you build a career around them.</p><span class="textlink">Read the tradeoffs →</span></a></div><div class="context-strip"><a href="https://ditchthescroll.com/books/" target="_blank" rel="noopener">Your Reading Atlas ↗</a><a href="#evidence">How your earlier work shaped this atlas →</a></div></section></div>`}
function card(s){const outlook=filters.horizon==='2034'?s.outlook2034:s.outlook2040;return `<article class="specialty-card"><div class="card-top"><span class="tag">${esc(getGroup(s.id))}</span><span class="card-symbol">${['◎','⌁','↗','◈'][order.indexOf(s.id)%4]}</span></div><h3>${esc(s.title)}</h3><p class="hook">${esc(s.hook)}</p><div class="outlook"><span class="eyebrow muted">${filters.horizon==='2034'?'2034 ENTRY OUTLOOK':'2040s POSSIBILITY'}</span><p>${esc(outlook)}</p></div><div class="card-actions"><button class="open-path" data-action="open" data-id="${s.id}">Open field notes <span aria-hidden="true">↗</span></button><button class="iconbutton" data-action="save" data-id="${s.id}" aria-pressed="${saved.has(s.id)}" aria-label="Save ${esc(s.title)}">${saved.has(s.id)?'★':'☆'}</button></div><button class="compare-add" data-action="compare-add" data-id="${s.id}" aria-pressed="${compare.has(s.id)}">${compare.has(s.id)?'✓ Added to comparison':'+ Compare this path'}</button></article>`}
function explore(){return `<div class="wrap">${intro('THE FIELD GUIDE / 26 MAJOR PATHS','A whole universe<br>of <em>specialization.</em>','A degree is the foundation. A specialty is the capability you develop. A niche is the difficult problem people eventually trust you to solve.')}<div class="filter-panel"><div class="search-row"><input id="specialty-search" type="search" aria-label="Search specialties, niches and companies" placeholder="Search robotics, engines, torpedoes, heat, companies…" value="${esc(filters.q)}"><select id="group-filter" aria-label="Filter by discipline"><option value="all">All engineering families</option>${Object.keys(groups).map(g=>`<option${filters.group===g?' selected':''}>${esc(g)}</option>`).join('')}</select><select id="outlook-filter" aria-label="Outlook horizon"><option value="2034"${filters.horizon==='2034'?' selected':''}>Outlook: entering in 2034</option><option value="2040"${filters.horizon==='2040'?' selected':''}>Outlook: the 2040s</option></select></div><div class="chips"><span class="filter-label">Explore by interest</span>${Object.entries(lensLabels).map(([id,t])=>`<button class="chip${filters.lens===id?' active':''}" data-action="lens" data-id="${id}" aria-pressed="${filters.lens===id}">${t}</button>`).join('')}</div></div><div class="result-info"><span id="result-count" aria-live="polite"></span><span>Save favorites ☆ · Compare up to 3 · Rankings are editorial</span></div><div class="specialty-grid" id="specialty-results"></div><section class="section"><div class="eyebrow">HOW THE LAYERS FIT TOGETHER</div><h2>You can go much deeper.</h2><p class="lead">“Space” is a destination and industry. “Robotics” is a field. The useful specialty often lives several layers below.</p><div class="explainer-grid"><div><div class="n">01 / DEGREE</div><h3>Aerospace engineering</h3><p>Mechanics, fluids, structures, dynamics, propulsion, computation, and design.</p></div><div><div class="n">02 / DISCIPLINE</div><h3>Robotics & controls</h3><p>Motion, sensing, estimation, actuation, and feedback.</p></div><div><div class="n">03 / APPLICATION</div><h3>Orbital servicing</h3><p>Inspecting, capturing, maintaining, and upgrading spacecraft.</p></div><div><div class="n">04 / DEEP NICHE</div><h3>Contact dynamics</h3><p>Making a robot touch a flexible, free-floating object without destabilizing the combined system.</p></div></div>${refs(['rt-taxonomy','rt-isam'])}</section></div>`}
function results(){let items=specialties.filter(s=>(filters.group==='all'||getGroup(s.id)===filters.group)&&(filters.lens==='all'||lensIds[filters.lens].includes(s.id))&&JSON.stringify(s).toLowerCase().includes(filters.q.toLowerCase().trim()));if(filters.lens!=='all')items.sort((a,b)=>lensIds[filters.lens].indexOf(a.id)-lensIds[filters.lens].indexOf(b.id));$('#result-count').textContent=`${items.length} of ${specialties.length} paths · ${filters.lens==='all'?'Recommended starting order':lensLabels[filters.lens]}`;$('#specialty-results').innerHTML=items.length?items.map(card).join(''):'<div class="empty"><h3>No paths match those filters.</h3><p>Try a broader term or reset the filters.</p><button data-action="reset-filters">Reset filters</button></div>'}
const missions={yard:{name:'The orbital workshop',short:'Orbital<br>workshop',tag:'REPAIR / ASSEMBLE / KEEP OPERATING',intro:'A robot reaches for a replaceable module. The challenge is everything that has to go right before—and after—its gripper closes.',roles:[['spacecraft-mechanisms','The interface must cooperate','Capture fixtures, latches, alignment, stiffness, lubrication, and access determine whether servicing is physically possible.'],['space-robotics','The arm must understand contact','A successful grasp changes the dynamics. Sensing and control must deal with uncertain forces and imperfect geometry.'],['gnc','The entire vehicle must stay controlled','Moving an arm can move its spacecraft. Robot motion and vehicle attitude cannot be treated as unrelated.'],['thermal-cryogenic','The repaired hardware must survive','Temperature, thermal interfaces, and possibly fluid connections are part of the operation.'],['systems-test','Someone must prove it worked','Verification links the command, physical state, measurements, and criteria for returning to service.'],['orbital-servicing','The mission must be worth doing','Logistics, client design, interfaces, and the economics of repair decide whether the workshop has customers.']]},habitat:{name:'A habitat people can trust',short:'Human<br>habitat',tag:'AIR / WATER / HEAT / HUMAN WORK',intro:'Picture a place that stays livable even when a pump fails. The most important engineering may be the part that makes an ordinary repair possible.',roles:[['habitats-life-support','Keep the environment habitable','Air, water, contaminants, resource inventories, sensing, and redundancy must work as an integrated system.'],['thermal-cryogenic','Move the waste heat','Every powered system and every person adds heat. The environment limits how the habitat rejects it.'],['space-power','Keep critical loads running','Generation, storage, distribution, and load priorities support continuous operations.'],['eva-human-systems','Design for the people doing the work','Reach, visibility, displays, maintenance access, workload, and suit interfaces affect safety and productivity.'],['space-robotics','Let machines handle routine checks','Inspection and caretaking can reduce crew workload without assuming complete autonomy.'],['crew-operations','Turn hardware into a working place','Procedures, training, diagnosis, logistics, and decisions under pressure sustain daily life.']]},moon:{name:'The lunar construction site',short:'Lunar<br>worksite',tag:'MOBILITY / DUST / ENERGY / CONSTRUCTION',intro:'A lunar worksite is a possible future customer, not an assured 2034 employer. Its problems make useful specialties visible today.',roles:[['lunar-construction','Work with unfamiliar ground','Traction, excavation reaction forces, dust, terrain, and available energy shape what a robot can accomplish.'],['spacecraft-mechanisms','Make mechanisms tolerate the place','Joints, seals, connectors, and deployable hardware must meet their actual environmental requirements.'],['space-robotics','Operate with imperfect help','Navigation, manipulation, autonomy, and teleoperation must fit communications and terrain constraints.'],['space-power','Make the work energetically possible','Storage, generation, distribution, and interruptions can dominate the construction plan.'],['structures-manufacturing','Know what you actually built','Fabrication, dimensional control, material variation, and inspection determine whether structures are usable.'],['systems-test','Integrate a complete work system','A productive site needs delivery, setup, tools, spares, maintenance, and acceptance criteria.']]},ocean:{name:'The autonomous ocean vehicle',short:'Ocean<br>robot',tag:'PRESSURE / NAVIGATION / INSPECTION',intro:'An ocean robot makes the space connection concrete: the same methods meet different physics, different communications, and different failure modes.',roles:[['underwater-robotics','Understand the environment','Pressure, buoyancy, corrosion, drag, and acoustics demand genuine marine expertise.'],['gnc','Navigate when GPS is unavailable','Estimation must manage drifting measurements and intermittent external references.'],['spacecraft-mechanisms','Build reliable moving interfaces','Actuators and connectors need environment-specific design. Space-qualified parts are not automatically subsea parts.'],['avionics','Make computing recover predictably','Fault detection, embedded systems, software behavior, and logging support recoverable missions.'],['systems-test','Test the recovery plan','Reliability includes what happens when sensing, propulsion, or communication degrades.'],['humanoids-wearables','Borrow from general robotics','Manipulation and mechatronics offer useful techniques; the robot need not have a human shape.']]}};
function missionContent(){const m=missions[missionId];return `<div class="mission-layout"><div class="mission-stage"><div class="mission-title">${m.tag}</div><div class="orbit-map"><div class="mission-core">${m.short}</div>${m.roles.map(r=>`<button class="mission-node" data-action="open" data-id="${r[0]}">${esc(byId[r[0]]?.title||r[0])}</button>`).join('')}</div><p class="scenario-note">Illustrative system map. Click a subsystem to meet its specialists.</p></div><div><h2 style="font-size:32px">${m.name}</h2><p>${m.intro}</p>${m.roles.map(r=>`<div class="mission-problem"><h4>${r[1]}</h4><p>${r[2]}</p><a href="#path/${r[0]}">Explore the specialty →</a></div>`).join('')}</div></div>`}
function missionPage(){return `<div class="wrap">${intro('THE MACHINES / UNDERSTAND THE WHOLE','One mission.<br><em>Many kinds of genius.</em>','A spacecraft is a meeting place for specialists. Explore the problems underneath the picture, then follow the ones that make you curious.')}<div class="tabs">${Object.entries(missions).map(([id,m])=>`<button class="${id===missionId?'active':''}" data-action="mission" data-id="${id}">${m.name}</button>`).join('')}</div><div id="mission-content">${missionContent()}</div><div class="ribbon"><p><strong>The outside-the-box opportunity:</strong> become fluent at an interface other teams struggle with—robot contact and spacecraft dynamics; life support and fault diagnosis; mechanisms and maintainability. These combinations are judgments about useful capability, not guaranteed job titles.</p>${refs(['sp06','sp11','sp13','rt-isam'])}</div></div>`}
function routeContent(){const r=E.routes.find(r=>r.id===routeId);return `<div class="route-detail"><div class="eyebrow">${r.icon}</div><h2>${r.title}</h2><p class="lead">${r.description}</p><div class="route-chain"><div class="route-step"><div class="eyebrow">01 / FOUNDATION</div><h4>Your degree route</h4><p>${r.degree}</p></div><div class="route-step"><div class="eyebrow">02 / DEPTH</div><h4>Your technical identity</h4><p>${r.depth}</p></div><div class="route-step"><div class="eyebrow">03 / EVIDENCE</div><h4>Your proof of capability</h4><p>${r.proof}</p></div></div><div class="two-col"><div><h4>What could change your mind?</h4><p>${r.fork}</p></div><div><h4>The tradeoff to accept</h4><p>${r.caution}</p></div></div><button class="primary" data-action="route-explore" data-id="${r.search}">Explore the relevant specialties ↗</button>${r.id==='crew'?'<a class="button" style="margin-left:10px" href="#spaceflight">See the flight pathways →</a>':''}${refs(r.id==='crew'?['sp01','sp02']:['rt-ucsd-ae','rt-ucsd-me','rt-ucsd-curriculum'])}</div>`}
function routePage(){return `<div class="wrap">${intro('YOUR ROUTE / PERSONAL FIT, NOT A DESTINY','An aerospace education.<br><em>A builder’s center of gravity.</em>','Your recent work moved from a broad EE/hardware plan toward aerospace, mechanisms, spacecraft, robotic industry, and places humans can live. This recommendation follows that newer direction.')}<div class="route-choice">${E.routes.map(r=>`<button data-action="route" data-id="${r.id}" class="${routeId===r.id?'active':''}"><span class="eyebrow">${r.icon}</span><strong>${r.title}</strong><span>${r.description}</span></button>`).join('')}</div><div id="route-content">${routeContent()}</div>
<section class="section"><div class="section-top"><div><div class="eyebrow">THE DEGREE IS A STARTING PLATFORM</div><h2>AE, ME, or EE?</h2></div><p>Choose the curriculum and project access that develop the work you want to do. Job titles rarely map one-to-one to degrees.</p></div><div class="table-scroll"><table class="degree-table"><thead><tr><th>Route</th><th>Natural center</th><th>Why it fits you</th><th>What to add</th></tr></thead><tbody><tr><td>Aerospace engineering</td><td>Vehicles, flight, orbital motion, structures, propulsion, dynamics.</td><td>Your current preference. Strong route toward understanding spacecraft and aircraft as interacting systems.</td><td>Mechanism design, robotics, fabrication, electronics literacy, and serious test work.</td></tr><tr><td>Mechanical engineering</td><td>Mechanisms, machines, thermofluids, materials, manufacturing.</td><td>A serious alternative if joints, actuators, assemblies, and making hardware become your favorite part.</td><td>Space environment, orbital/vehicle dynamics, space projects, relevant controls.</td></tr><tr><td>Electrical / computer engineering</td><td>Electronics, sensing, power, communications, computation, control.</td><td>Relevant if you fall in love with a robot’s sensing or electrical subsystems. Not a reason to override your aerospace preference.</td><td>Mechanical/vehicle context and multidisciplinary hardware teams.</td></tr><tr><td>Specialized graduate study</td><td>One deeper question in robotics, controls, fluids, materials, human systems, or other fields.</td><td>Useful when a target role or research question requires methods beyond the BS.</td><td>Choose advisor, laboratory, project, funding, and outcomes—not only degree title.</td></tr></tbody></table></div>${refs(['rt-ucsd-curriculum','rt-ucsd-me'])}<div class="ribbon"><p><strong>UCSD today:</strong> the AE options are Astrodynamics and Space Applications, Aerothermodynamics, and Flight Dynamics and Controls. The last is a particularly promising starting point for your robotics/vehicle-motion interests. Plan electives early; recheck the catalog and transfer requirements for your actual enrollment year.</p>${refs(['rt-ucsd-ae'])}</div></section>
<section class="section two-col"><div><div class="eyebrow">DECISIONS WHEN THEY BECOME USEFUL</div><h2>Let experience<br><em>sharpen the choice.</em></h2><p>This is a sequence of decisions, not a weekly productivity schedule. Your 2033 graduation is an assumption to plan around; prerequisite chains, transfer timing, and workload determine what is possible.</p><p>You can contribute through student projects and internships before 2034. A master’s may move full-time entry later.</p></div><div class="roadmap"><div class="roadmap-item"><span>2026—29</span><div><h3>Build the common foundation</h3><p>Mathematics, physics, programming, technical drawing, and small physical projects. Notice what kind of problem you keep wanting to understand.</p></div></div><div class="roadmap-item"><span>2030—31</span><div><h3>Test two or three paths</h3><p>Use classes, labs, design teams, research, and internships to compare mechanisms, controls, and thermofluids. Plan the eventual specialization around actual offerings.</p></div></div><div class="roadmap-item"><span>2032—33</span><div><h3>Own a subsystem</h3><p>Requirements, calculations, drawings or software, tests, failures, revisions, and measured results. Deep ownership matters more than an impressive project name.</p></div></div><div class="roadmap-item"><span>2034—40</span><div><h3>Become trusted at the hard part</h3><p>Join useful work, learn from experienced engineers, and deepen your craft. Move toward space infrastructure as real programs create openings.</p></div></div></div></section>
<section class="section"><div class="eyebrow">WHY THE MATH MATTERS</div><h2>The machinery beneath the machinery.</h2><p class="lead">You do not need to understand advanced control today. The foundations are how you earn access to it.</p><div class="math-grid">${E.math.map(([t,d])=>`<div class="math-card"><h4>${t}</h4><p>${d}</p></div>`).join('')}</div><div class="context-strip"><a href="https://ditchthescroll.com/books/" target="_blank" rel="noopener">Continue through your Reading Atlas ↗</a><a href="#pay">Pay, AI, and choosing depth →</a></div></section></div>`}
function flightPage(){const f=R.spaceSections.flying,paths=R.spaceSections.spaceflightPaths;return `<div class="wrap">${intro('THE HUMAN QUESTION / A RARE AND REAL AMBITION','Build for space.<br><em>Could you work there, too?</em>','Yes, engineers can become crewmembers. But “aerospace engineer” describes an engineering profession, while “astronaut” or “mission specialist” describes a selected operational role.')}<div class="two-col"><div><div class="pullquote">Become someone a mission would trust with both the system and the situation.</div><p>${esc(f.text)}</p><p>There is no defensible ranking of specialties by their odds of getting a seat. The strongest strategy is technical depth plus broad operational usefulness—and a career you would still love from Earth.</p></div><div class="panel"><div class="eyebrow">NASA’S CURRENT BASELINE</div><h3>Eligibility is the first gate.</h3><p>${esc(f.currentEligibility)}</p><div class="fact-box"><div class="big">10 / 8,000+</div><p>NASA’s 2025 candidate selection. This illustrates rarity; it is not your individual probability, and selection does not mean an immediate flight.</p></div>${refs(f.sourceIds)}</div></div><section class="section"><div class="eyebrow">FOUR DIFFERENT ROUTES</div><h2>Some exist. Some are possibilities.</h2><div class="two-col">${paths.map(p=>`<article class="panel"><span class="tag ${p.status.startsWith('Plausible')?'orange':'lime'}">${esc(p.status)}</span><h3 style="margin-top:20px">${esc(p.name)}</h3><p>${esc(p.path)}</p><h4>Relevant expertise</h4><p>${esc(p.specialties)}</p><h4>The reality</h4><p>${esc(p.tradeoff)}</p>${refs(p.sourceIds)}</article>`).join('')}</div></section><section class="section"><div class="section-top"><div><div class="eyebrow">IF YOU WANT TO BE USEFUL THERE</div><h2>Build a crew-relevant combination.</h2></div><p>These are mission-relevance judgments, not predictions of who will be selected.</p></div><div class="three-col"><article class="panel"><h3>The robotic operator</h3><p>Understand the manipulator, its sensors, its failure modes, and the spacecraft around it. Add procedures, training, and calm operational judgment.</p>${pathButton('space-robotics')}${pathButton('crew-operations')}</article><article class="panel"><h3>The habitat troubleshooter</h3><p>Know how air, water, heat, power, and control systems interact. Be able to diagnose a problem and verify that the recovery really worked.</p>${pathButton('habitats-life-support')}${pathButton('systems-test')}</article><article class="panel"><h3>The human-systems engineer</h3><p>Understand crew interfaces, EVA tasks, tools, workload, and the practical constraints of a person working in a demanding environment.</p>${pathButton('eva-human-systems')}${pathButton('spacecraft-mechanisms')}</article></div><div class="ribbon"><p><strong>Your timeline:</strong> ${esc(f.timing)}</p></div></section><section class="section two-col"><div><div class="eyebrow">THE DEGREE QUESTION</div><h2>Does it have to be aerospace?</h2><p>${esc(f.degree)}</p><p>Engineers share crew work with scientists, physicians, pilots, and other mission specialists. Training is broad because a small crew cannot carry a separate person for every subsystem.</p>${refs(['sp02','sp03'])}</div><div><div class="eyebrow">THE COMMERCIAL EXAMPLES</div><h2>Possibility has precedents.</h2><p>Sarah Gillis and Anna Menon flew on Polaris Dawn after engineering and operational work at SpaceX. Those are relevant examples of technical employees flying, not a reliable promotion ladder for employees generally.</p><p>Future station-maintenance or lunar field roles may emerge. Look for actual sponsored missions and hiring criteria before treating them as an established profession.</p>${refs(['sp04','sp05','sp19'])}</div></section></div>`}
function horizonContent(){const h=E.horizons[horizon];return `<div class="horizon-display"><div class="eyebrow">${horizon} / ${h.label}</div><h2>${h.subtitle}</h2><p class="lead">${h.thesis}</p><div class="two-col"><div><h4>Durable work / reasonable planning</h4>${ul(h.likely)}</div><div><h4>Conditional upside / needs evidence</h4>${ul(h.conditional)}</div></div><div class="rule"></div><p class="no-bottom"><strong>Avoid the fragile bet:</strong> ${h.avoid}</p></div>`}
function horizonsPage(){return `<div class="wrap">${intro('THE OUTLOOK / SCENARIOS, NOT PROPHECY','A future worth preparing for.<br><em>Several ways it could unfold.</em>','The engineering problems are more predictable than the market size, company winners, or launch dates. Build around the former. Watch evidence for the latter.')}<div class="horizon-switch">${Object.keys(E.horizons).map(y=>`<button data-action="horizon" data-id="${y}" class="${horizon===y?'active':''}">${y==='2042'?'2040s':y}</button>`).join('')}</div><div id="horizon-content">${horizonContent()}</div><section class="section"><div class="eyebrow">THREE POSSIBLE MARKET SHAPES</div><div class="three-col">${R.spaceSections.scenarios.map(s=>`<article class="panel"><span class="tag">${esc(s.period)}</span><h3 style="margin-top:18px">${esc(s.name)}</h3><p>${esc(s.description)}</p><h4>How to position yourself</h4><p>${esc(s.strategy)}</p><p class="small">${esc(s.evidence)}</p>${refs(s.sourceIds)}</article>`).join('')}</div></section><section class="section"><div class="eyebrow">YOUR FORECAST DASHBOARD</div><h2>Watch signals that cost something.</h2><p class="lead">Revisit this evidence when choosing electives around 2030–31 and when applying around 2033–34. This site is a dated research snapshot, not a live feed.</p><div class="signal-row"><strong>What to watch</strong><strong>What would strengthen the case</strong><strong>What it means for your choice</strong></div>${[
['Commercial habitats','Successful operations, recurring users, funded follow-on hardware, and credible transport.','More reason to deepen ECLSS, thermal, maintainability, and operations.'],
['Orbital servicing','Repeated client missions and interfaces designed for service—not only one demonstration.','More reason to specialize in capture, contact dynamics, robot operations, and lifecycle design.'],
['Lunar infrastructure','Repeated cargo delivery, funded surface operations, and real procurement of power and equipment.','More reason to add dust, terramechanics, construction robotics, and surface thermal expertise.'],
['Microgravity manufacturing','Product quality, repeat customers, return logistics, and attractive economics.','More reason to combine process science, automation, quality, and payload engineering.'],
['AI in engineering','Measured changes in what teams automate and what they still need to validate physically.','Keep learning the tools while strengthening testing, model criticism, and subsystem ownership.']].map(row=>`<div class="signal-row">${row.map((s,i)=>i?`<p>${s}</p>`:`<strong>${s}</strong>`).join('')}</div>`).join('')}${refs(['sp14','sp19','rt-isam','sp30'])}</section><section class="section"><div class="eyebrow">AMBITIOUS COMBINATIONS</div><h2>The niche may live between fields.</h2><div class="two-col">${R.spaceSections.highValueCombinations.map(c=>`<div class="panel"><span class="tag">${esc(c.maturity)}</span><h3 style="margin-top:20px">${esc(c.name)}</h3><p class="analogy">${esc(c.combination)}</p><p class="no-bottom">${esc(c.why)}</p></div>`).join('')}</div></section></div>`}
function companyEntries(){const map=new Map();specialties.forEach(s=>s.companies.forEach(c=>{const key=c.name.toLowerCase();if(!map.has(key))map.set(key,{...c,ids:[]});map.get(key).ids.push(s.id)}));return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function companiesPage(){return `<div class="wrap">${intro('THE ECOSYSTEM / WHO DOES THE WORK TODAY','Meet the builders.<br><em>Follow the capability.</em>','Companies, research institutions, and agencies are examples observed in current sources. These are not promised 2034 employers, open vacancies, or endorsements.')}<div class="search-row"><input id="company-search" type="search" aria-label="Search companies and work" placeholder="Find a company or capability…"></div><p class="small" style="margin:18px 0">Corporate names and ownership change. Each link points to the relevant capability or official source; always verify current roles and eligibility.</p><div class="company-grid" id="company-results"></div></div>`}
function companyResults(q=''){const list=companyEntries().filter(c=>JSON.stringify(c).toLowerCase().includes(q.toLowerCase()));$('#company-results').innerHTML=list.map(c=>`<article class="company-card"><h3>${esc(c.name)}</h3><p>${esc(c.why)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener">Official capability / source ↗</a><div>${c.ids.map(id=>pathButton(id)).join('')}</div></article>`).join('')||'<div class="empty">No matching organizations.</div>'}
function payPage(){const pay=R.optionSections.find(s=>s.id==='specialist-pay');return `<div class="wrap">${intro('THE TRADEOFFS / MONEY, AI & OPTIONALITY','Choose useful depth.<br><em>Keep room to move.</em>','Space versus defense is not a clean salary ladder. Specialist versus generalist is not one either. You want technical depth that matters to a real program.')}<div class="two-col"><div><h2>Deep does not mean narrow forever.</h2>${pay.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="ribbon"><p><strong>For you:</strong> a broad AE foundation + mechanisms or robotics depth + real integration and testing is a stronger initial strategy than chasing the smallest-sounding niche.</p></div></div><div class="panel"><div class="eyebrow">CURRENT CONTEXT / NOT YOUR FUTURE OFFER</div><h3>U.S. occupational medians</h3><p class="small">${esc(pay.payData.measure)}. Nominal U.S. dollars. These groups have different experience mixes and responsibilities.</p>${pay.payData.rows.map(r=>`<div class="pay-row"><span>${esc(r.occupation)}</span><strong>$${r.median.toLocaleString('en-US')}</strong></div>`).join('')}<p class="small" style="margin-top:18px">Not starting pay. Not 2034 forecasts. These data do not separate space from defense or establish a causal specialization premium.</p>${refs(pay.sourceIds)}</div></div><section class="section"><div class="eyebrow">QUESTIONS WORTH CHALLENGING</div><h2>The assumptions underneath the decision.</h2><div class="accordions">${E.faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>${refs(['op-gao26','op-atlas','op-valkyrie','op-bls-ae'])}</section><section class="section two-col"><div><div class="eyebrow">YOUR “IRON MAN” QUESTION</div><h2>Pick the part of the dream<br>you want to engineer.</h2><p>Missile and torpedo programs employ people with depth in vehicles, propulsion, controls, materials, electronics, manufacturing, and test. Those are technical crafts you can also use elsewhere. Weapons development is not a single specialty and there is no reason to assume it will run out of problems.</p><p>For wearable machines, the route is often robotics, biomechanics, actuation, power, thermal design, and human factors. For extraordinary flying vehicles, the route is aerospace. Both require many specialists.</p><button class="primary" data-action="route-explore" data-id="human">Explore the real disciplines ↗</button>${refs(['op-gao26','op-ekso','op-atlas'])}</div><div><div class="eyebrow">THE PART YOU CANNOT OUTSOURCE TO A FORECAST</div><h2>Try the work itself.</h2><p>Do you enjoy analyzing an unstable response? Debugging a sensor? Figuring out why a joint binds? Running a careful experiment? Reading papers? Improving a manufacturing process?</p><p>Those reactions are more useful for choosing a specialty than liking the finished machine. Internships, laboratories, and team projects turn an imagined career into something you can evaluate.</p><p>Let your first depth be a strong hypothesis. You are allowed to revise it.</p></div></section></div>`}
function evidencePage(){return `<div class="wrap">${intro('THE EVIDENCE / READ THE FOOTNOTES','Big ambition.<br><em>Visible assumptions.</em>','Research checked on 30 October 2026. Current facts, personal fit judgments, and longer-term scenarios are different kinds of claims.')}<div class="three-col"><div class="panel"><span class="tag lime">OBSERVED / CURRENT</span><h3 style="margin-top:20px">What exists today</h3><p>Official requirements, curricula, demonstrated missions, company capabilities, and dated wage statistics. Sources are linked next to the relevant claims.</p></div><div class="panel"><span class="tag">INTERPRETATION</span><h3 style="margin-top:20px">What seems right for you</h3><p>The ordering and combinations reflect your interests in mechanisms, motion, robots, aerospace, and habitation. They are judgments, not measured suitability scores.</p></div><div class="panel"><span class="tag orange">CONDITIONAL FORECAST</span><h3 style="margin-top:20px">What could become important</h3><p>2034 and 2040s outlooks extrapolate from physical needs and current activity. No company’s survival, program date, salary, or job market is guaranteed.</p></div></div><section class="section two-col"><div><h2>Built on your earlier work.</h2><p>The accessible portions of your robotics, Beyond Earth, and college/career chats were reviewed along with saved planning material. The later documents explicitly shifted the emphasis from EE toward aerospace and hands-on mechanisms; this atlas follows that update.</p><p>The saved <em>Building a Civilization Beyond Earth</em> manuscript contributed the habitation, maintenance, and systems perspective. <em>The Factory That Builds the Future</em> contributed assembly, manufacturing, metrology, and robotic industry. The reading and math work shaped the foundation-to-specialty route.</p><p class="small">Access limit: the chat reader could not return the oversized Factory chat turn and some earlier turns in other chats. Its saved manuscript and original brief were reviewed instead. This is not a claim to have read every message or every page of every prior document. Private transcripts and family details are not part of this site.</p></div><div><h2>How to use the evidence.</h2><p>Sources establish the specific capability or requirement described. A company product page does not establish future hiring; a roadmap does not establish a completed mission. A forecast labeled “high confidence” means confidence in underlying technical relevance, not a numerical probability or employment guarantee.</p><p>There are ${sources.length} reference records, with some repeated URLs because independent research tracks used the same source. The coverage is broad rather than literally exhaustive. The field notes contain ${specialties.reduce((n,s)=>n+s.niches.length,0)} nested niches.</p><p>Recheck programs, eligibility, curricula, and employer openings when the decisions become current. Use the outlook page’s evidence signals to update your view.</p><button data-action="download-research">Download the research data ↓</button></div></section><section class="section"><div class="section-top"><div><div class="eyebrow">PRIMARY-SOURCE LIBRARY</div><h2>Follow the trail.</h2></div><p>Government agencies, universities, research institutions, and the companies doing the work.</p></div><div class="search-row"><input id="source-search" type="search" aria-label="Search research sources" placeholder="Search NASA, salaries, mechanisms, university, company…"></div><div class="result-info"><span id="source-count"></span></div><div class="source-list" id="source-results"></div></section></div>`}
function sourceResults(q=''){const list=sources.filter(s=>JSON.stringify(s).toLowerCase().includes(q.toLowerCase()));$('#source-count').textContent=`${list.length} reference records`;$('#source-results').innerHTML=list.map(s=>`<article class="source-item"><span class="id">${esc(s.id)} / RESEARCHED OCT 2026</span><h3>${esc(s.title)}</h3><p>${esc(s.claim)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener">Open primary source ↗</a></article>`).join('')||'<div class="empty">No matching sources.</div>'}
function savedPage(){return `<div class="wrap">${intro('YOUR SHORTLIST / A DECISION IN PROGRESS','Keep the paths<br>that <em>pull you forward.</em>','Save the work that excites you, compare the tradeoffs, and record what would make you choose—or reject—a path.')}<div class="privacy-note">Saved paths and notes stay in this browser’s local storage. They are not synced across devices. Export them to keep a portable copy.</div><div class="space-between" style="margin-bottom:25px"><span>${saved.size} saved ${saved.size===1?'path':'paths'}</span><button data-action="export-saved">Export shortlist & notes ↓</button></div><div class="specialty-grid">${[...saved].map(id=>card(byId[id])).join('')||'<div class="empty"><h3>Your shortlist starts with curiosity.</h3><p>Use the star on any specialty to save it here.</p><a class="button primary" href="#explore">Explore the paths →</a></div>'}</div></div>`}
function detail(id){const s=byId[id];if(!s){toast('That specialty could not be found.');return}$('#detail-content').innerHTML=`<article class="detail-body"><span class="tag lime">${esc(getGroup(s.id))}</span><span class="tag">PROFESSIONAL SPECIALTY / NOT NECESSARILY A DEGREE TITLE</span><h2>${esc(s.title)}</h2><p class="lead">${esc(s.hook)}</p><div class="detail-actions"><button data-action="save" data-id="${id}" aria-pressed="${saved.has(id)}">${saved.has(id)?'★ Saved to your shortlist':'☆ Save this path'}</button><button data-action="compare-add" data-id="${id}">${compare.has(id)?'✓ Added to comparison':'+ Compare this path'}</button></div><h3>The actual work</h3><p>${esc(s.work)}</p>${s.evidenceNow?`<div class="ribbon"><p><strong>Evidence today:</strong> ${esc(s.evidenceNow)}</p></div>`:''}<h3>Specializations inside the specialization</h3><p>These are examples of how a broad field becomes a deep professional capability.</p>${s.niches.map((n,i)=>{if(typeof n==='object')return `<div class="niche"><h4>${esc(n.title||n.name)}</h4><p>${esc(n.description||n.work||'')}</p></div>`;const ix=n.indexOf(':');return `<div class="niche"><h4>${String(i+1).padStart(2,'0')} / ${esc(ix>0?n.slice(0,ix):n)}</h4>${ix>0?`<p>${esc(n.slice(ix+1).trim())}</p>`:''}</div>`}).join('')}<h3>The honest tradeoff</h3><div class="proscons"><div><h4>Why it could be exciting</h4>${ul(s.pros)}</div><div><h4>What you would be accepting</h4>${ul(s.cons)}</div></div><h3>Why it could matter when you arrive</h3><div class="two-col"><div><h4>Entering around 2034</h4><p>${esc(s.outlook2034)}</p></div><div><h4>Developing through the 2040s</h4><p>${esc(s.outlook2040)}</p></div></div><p class="small"><strong>Confidence judgment:</strong> ${esc(s.confidence)} These outlooks are inferences, not labor-market projections.</p><h3>How you develop the depth</h3><p>${esc(s.degrees)}</p><div>${s.skills.map(k=>`<span class="tag">${esc(k)}</span>`).join('')}</div><h4>An approachable first experiment</h4><p>${esc(s.starterProject)}</p><h3>Who works on this today?</h3><p class="small">Examples of companies, agencies, and research employers—not a list of current vacancies or guaranteed future employers.</p>${s.companies.map(c=>`<div class="detail-company"><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.name)} ↗</a><p>${esc(c.why)}</p></div>`).join('')}<h3>Would you personally work in space?</h3><p>${esc(s.spaceflight)}</p><a href="#spaceflight" class="textlink" data-action="flight-link">See the separate crew pathways →</a><h3>Your decision notes</h3><label class="note-label" for="path-note">What excites you? What would you want to try before committing?</label><textarea class="note-input" id="path-note" data-id="${id}" placeholder="Your notes stay in this browser…">${esc(notes[id]||'')}</textarea><p class="small" style="margin-top:8px">Notes save automatically. Export from your shortlist for a portable copy.</p><div class="detail-source-note"><strong>Evidence behind this field note</strong><p class="small" style="margin-top:8px">Sources support present capabilities and requirements. Future outlook and personal-fit advice are editorial judgments.</p>${refs(s.sourceIds)}</div></article>`;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;updateSaved()}
function compareTray(){const n=compare.size,t=$('#compare-tray');t.hidden=!n;t.innerHTML=`<span>${n} / 3 selected</span><span class="names">Compare the work, tradeoffs & routes</span><button class="primary" data-action="show-compare"${n<2?' disabled':''}>Compare paths →</button><button class="clear" data-action="clear-compare">Clear</button>`;$$('.compare-add').forEach(b=>{const on=compare.has(b.dataset.id);b.textContent=on?'✓ Added to comparison':'+ Compare this path';b.setAttribute('aria-pressed',on)})}
function showCompare(){if(compare.size<2)return;$('#comparison-content').innerHTML=`<div class="comparison-body"><p>Compare useful depth and tradeoffs. There is no invented salary or “chance of flying” score.</p><div class="comparison-table" style="grid-template-columns:repeat(${compare.size},1fr)">${[...compare].map(id=>{const s=byId[id];return `<article class="compare-col"><span class="tag">${esc(getGroup(id))}</span><h3 style="margin-top:20px">${esc(s.title)}</h3><p>${esc(s.hook)}</p><h4>The workday</h4><p>${esc(s.work)}</p><h4>Why choose it</h4>${ul(s.pros)}<h4>The costs</h4>${ul(s.cons)}<h4>2034 outlook</h4><p>${esc(s.outlook2034)}</p><h4>Education</h4><p>${esc(s.degrees)}</p><h4>Personally working in space</h4><p>${esc(s.spaceflight)}</p><button data-action="open" data-id="${id}">Read full field note →</button>${refs(s.sourceIds.slice(0,2))}</article>`}).join('')}</div></div>`;$('#comparison').showModal()}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const renderers={home,explore,missions:missionPage,route:routePage,spaceflight:flightPage,horizons:horizonsPage,companies:companiesPage,pay:payPage,evidence:evidencePage,saved:savedPage};
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();const hash=a.getAttribute('href');if(hash==='#main'){$('#main').focus();$('#main').scrollIntoView();return}location.hash=hash;});
function render(){const hash=decodeURIComponent(location.hash.slice(1)||'home');if(hash.startsWith('path/')){if(!$('#main').innerHTML){activeView='explore';$('#main').innerHTML=explore();results()}detail(hash.slice(5));return}if($('#detail').open)$('#detail').close();if($('#comparison').open)$('#comparison').close();activeView=renderers[hash]?hash:'home';returnView=activeView;$('#main').innerHTML=renderers[activeView]();if(activeView==='explore')results();if(activeView==='companies')companyResults();if(activeView==='evidence')sourceResults();$$('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+activeView));$('nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');updateSaved();compareTray();window.scrollTo(0,0);document.title=`${activeView==='home'?'Your Aerospace Future':({explore:'Specialty Explorer',missions:'The Machines',route:'Your Route',spaceflight:'Work in Space',horizons:'2034 & Beyond',companies:'The Employer Map',pay:'Pay & Tradeoffs',evidence:'The Evidence',saved:'Your Shortlist'})[activeView]} · The Frontier Atlas`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case'open':if($('#comparison').open)$('#comparison').close();location.hash='path/'+id;break;case'close-dialog':$('#detail').close();if(location.hash.startsWith('#path/'))location.hash=returnView;break;case'close-compare':$('#comparison').close();break;case'flight-link':$('#detail').close();break;case'save':saved.has(id)?saved.delete(id):saved.add(id);persist();if(activeView==='saved'&&!$('#detail').open)render();break;case'show-saved':location.hash='saved';break;case'compare-add':if(compare.has(id))compare.delete(id);else if(compare.size<3)compare.add(id);else{toast('Compare up to three paths. Remove one to add another.');break}compareTray();b.textContent=compare.has(id)?'✓ Added to comparison':'+ Compare this path';toast(`${compare.size} paths selected`);break;case'clear-compare':compare.clear();compareTray();break;case'show-compare':showCompare();break;case'lens':filters.lens=id;$$('[data-action="lens"]').forEach(x=>{x.classList.toggle('active',x.dataset.id===id);x.setAttribute('aria-pressed',x.dataset.id===id)});results();break;case'reset-filters':filters={q:'',group:'all',lens:'all',horizon:'2034'};render();break;case'mission':missionId=id;$$('[data-action="mission"]').forEach(x=>x.classList.toggle('active',x.dataset.id===id));$('#mission-content').innerHTML=missionContent();break;case'route':routeId=id;$$('[data-action="route"]').forEach(x=>x.classList.toggle('active',x.dataset.id===id));$('#route-content').innerHTML=routeContent();$('#route-content').scrollIntoView({behavior:'smooth',block:'start'});break;case'route-explore':filters={q:'',group:'all',lens:id,horizon:'2034'};location.hash='explore';break;case'horizon':horizon=id;$$('[data-action="horizon"]').forEach(x=>x.classList.toggle('active',x.dataset.id===id));$('#horizon-content').innerHTML=horizonContent();break;case'export-saved':download('frontier-atlas-shortlist.json',{exported:new Date().toISOString(),saved:[...saved].map(id=>({id,title:byId[id].title,note:notes[id]||''})),notes});break;case'download-research':download('frontier-atlas-research.json',{researchedAt:'2026-10-30',method:'Current evidence plus labeled scenarios; not a hiring or salary prediction.',specialties,sources});break;}});
document.addEventListener('input',e=>{if(e.target.id==='specialty-search'){filters.q=e.target.value;results()}if(e.target.id==='company-search')companyResults(e.target.value);if(e.target.id==='source-search')sourceResults(e.target.value);if(e.target.id==='path-note'){notes[e.target.dataset.id]=e.target.value;persist()}});
document.addEventListener('change',e=>{if(e.target.id==='group-filter'){filters.group=e.target.value;results()}if(e.target.id==='outlook-filter'){filters.horizon=e.target.value;results()}});
$('.menu-toggle').addEventListener('click',()=>{$('nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',$('nav').classList.contains('open'))});
$('#detail').addEventListener('cancel',()=>{if(location.hash.startsWith('#path/'))location.hash=returnView});
window.addEventListener('hashchange',render);render();
